DO $dairy$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "arequipe-casero", "public_path": "/arequipe-casero", "title": "Arequipe casero desde leche y azúcar, paso a paso", "excerpt": "Prepara arequipe casero desde leche y azúcar, sin cocinar latas. Fotos del color y punto final, rendimiento aproximado y consejos para guardarlo en nevera.", "summary": "El arequipe se logra reduciendo leche y azúcar hasta obtener una crema café, espesa y untable. Esta receta no lleva arroz ni almidón y es distinta del manjar blanco del Valle. Rinde aproximadamente 500 g, según la reducción.", "content_html": "<p>El arequipe se logra reduciendo leche y azúcar hasta obtener una crema café, espesa y untable. Esta receta no lleva arroz ni almidón y es distinta del manjar blanco del Valle. Rinde aproximadamente 500 g, según la reducción.</p>", "notes": "<h3>Consejos y conservación</h3><p>Mantén tapado y usa en 5–7 días como pauta doméstica prudente. Si queda demasiado firme, afloja una porción con un poco de leche caliente y úsala pronto. Si duplicas, emplea una olla adecuada y guíate por el punto, no duplicando automáticamente el tiempo. Sin prueba de cocina propia. Contiene leche. Usa utensilios limpios y desinfectados y conserva a 4 °C o menos. No es una conserva para guardar a temperatura ambiente.</p><ul><li><a href=\"https://www.mycolombianrecipes.com/arequipe-or-dulce-de-leche/\">My Colombian Recipes — arequipe cooking technique</a></li><li><a href=\"https://movil.colombiaaprende.edu.co/sites/default/files/files_public/aprenderencasa/secretos-para-contar/la-casa-y-el-campo.pdf\">Secretos para contar — milk sweets, cultural reference</a></li></ul>", "ingredients": [{"name": "leche entera pasteurizada", "amount": "1000", "unit": "ml"}, {"name": "azúcar blanco", "amount": "250", "unit": "g"}, {"name": "bicarbonato de sodio alimentario", "amount": "1", "unit": "g"}, {"name": "extracto de vainilla", "amount": "3", "unit": "ml"}], "steps": [{"title": "Mezcla y calienta", "content": "Pon leche, azúcar y bicarbonato en una olla amplia, alta y de fondo grueso. Remueve a fuego medio-bajo hasta disolver. Cuando suba espuma, baja el fuego; debe sobrar espacio para que no se desborde.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-01.webp", "image_alt": "Mezcla y calienta — Arequipe casero desde leche y azúcar, paso a paso"}, {"title": "Reduce con paciencia", "content": "Cocina destapado a fuego bajo unos 90–140 minutos. Remueve el fondo con frecuencia; cuando tome color café y espese, remueve casi continuamente. Debe burbujear suavemente, sin pegarse ni quemarse.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-02.webp", "image_alt": "Reduce con paciencia — Arequipe casero desde leche y azúcar, paso a paso"}, {"title": "Busca el punto", "content": "Añade la vainilla al final. Pasa la cuchara por el fondo: debe dejar un camino que tarde unos segundos en cerrarse. Una cucharadita en plato frío queda espesa pero untable. Retira algo más fluido de lo deseado porque espesa al enfriar; el rendimiento ronda 500 g.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-03.webp", "image_alt": "Busca el punto — Arequipe casero desde leche y azúcar, paso a paso"}, {"title": "Enfría y guarda", "content": "Pasa a un recipiente limpio resistente al calor. Enfría en baño de agua fría sin que entre agua, removiendo de vez en cuando. Refrigera antes de 2 horas y espera aproximadamente 1 hora antes de servir.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-04.webp", "image_alt": "Enfría y guarda — Arequipe casero desde leche y azúcar, paso a paso"}], "category": "Postres", "course": "Postres", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 140, "total_time_minutes": 210, "servings": 20, "image_url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "alt": "Arequipe casero desde leche y azúcar, paso a paso"}], "video_urls": [], "keywords": ["Arequipe casero desde leche y azúcar, paso a paso"], "nutrition": {"calories": 82, "protein_g": 1.6, "carbs_g": 15, "fat_g": 1.7, "serving_size": "1 de 20 porciones, unos 25 g", "estimated": true, "note": "Estimación por porción; el rendimiento, la humedad y la marca cambian los valores.", "source": "USDA FoodData Central generic whole milk and sugar composition", "method": "1030 g whole milk (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat/100 g) plus250 g sugar (400 kcal and100 g carbohydrate/100 g), divided by20. Small vanilla contribution rounded into calories. Assumed500 g yield,25 g/portion. No whey drained; only water evaporated."}, "seo": {"title": "Arequipe casero desde leche y azúcar, paso a paso", "description": "Prepara arequipe casero desde leche y azúcar, sin cocinar latas. Fotos del color y punto final, rendimiento aproximado y consejos para guardarlo en nevera.", "author": "Néstor Bastidas", "image_alt": "Arequipe casero desde leche y azúcar, paso a paso", "image_variants": ["https://manualdecocina.com/recetas/arequipe-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-16x9.webp"], "faq": [{"q": "¿Es igual al manjar blanco del Valle?", "a": "No en esta colección. El manjar blanco tiene su receta propia; este arequipe no lleva arroz ni almidón."}, {"q": "¿Puedo cocinarlo dentro de una lata cerrada?", "a": "Esta ficha cocina leche y azúcar en olla abierta. No calientes latas cerradas para seguir este método."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "en", "slug": "homemade-colombian-arequipe", "public_path": "/en/homemade-colombian-arequipe", "title": "Homemade Colombian arequipe from milk and sugar", "excerpt": "Make Colombian arequipe from milk and sugar without cooking cans. Photos show color and thickness, approximate yield and refrigerated storage guidance.", "summary": "Arequipe is milk and sugar slowly reduced into a thick caramel-brown spread. This recipe has no rice or starch and differs from Valle-style manjar blanco. It yields approximately 500 g, depending on reduction.", "content_html": "<p>Arequipe is milk and sugar slowly reduced into a thick caramel-brown spread. This recipe has no rice or starch and differs from Valle-style manjar blanco. It yields approximately 500 g, depending on reduction.</p>", "notes": "<h3>Tips and storage</h3><p>Keep covered and use within 5–7 days as a cautious home-storage guide. Loosen an overly firm portion with a little hot milk and use promptly. When doubling, use a suitable pot and judge the endpoint rather than automatically doubling time. Not kitchen-tested. Contains milk. Use clean, sanitized equipment and refrigerate at 4 °C or below. This is not a shelf-stable canned product.</p><ul><li><a href=\"https://www.mycolombianrecipes.com/arequipe-or-dulce-de-leche/\">My Colombian Recipes — arequipe cooking technique</a></li><li><a href=\"https://movil.colombiaaprende.edu.co/sites/default/files/files_public/aprenderencasa/secretos-para-contar/la-casa-y-el-campo.pdf\">Secretos para contar — milk sweets, cultural reference</a></li></ul>", "ingredients": [{"name": "pasteurized whole milk", "amount": "1000", "unit": "ml"}, {"name": "white sugar", "amount": "250", "unit": "g"}, {"name": "food-grade baking soda", "amount": "1", "unit": "g"}, {"name": "vanilla extract", "amount": "3", "unit": "ml"}], "steps": [{"title": "Combine and heat", "content": "Put milk, sugar and baking soda in a wide, deep heavy-based pot. Stir over medium-low heat until dissolved. Lower heat when foam rises; leave ample headroom to prevent boiling over.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-01.webp", "image_alt": "Combine and heat — Homemade Colombian arequipe from milk and sugar"}, {"title": "Reduce patiently", "content": "Cook uncovered over low heat for about 90–140 minutes. Stir the bottom regularly, then almost constantly as it turns brown and thickens. Maintain gentle bubbling without scorching.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-02.webp", "image_alt": "Reduce patiently — Homemade Colombian arequipe from milk and sugar"}, {"title": "Check the endpoint", "content": "Stir in vanilla near the end. A spoon drawn across the bottom should leave a trail that closes after a few seconds. A teaspoon on a cold plate should be thick but spreadable. Remove slightly looser than desired, as it thickens when cool; yield is about 500 g.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-03.webp", "image_alt": "Check the endpoint — Homemade Colombian arequipe from milk and sugar"}, {"title": "Cool and store", "content": "Transfer to a clean heatproof container. Cool in a cold-water bath without letting water enter, stirring occasionally. Refrigerate within 2 hours and allow about 1 hour before serving.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-04.webp", "image_alt": "Cool and store — Homemade Colombian arequipe from milk and sugar"}], "category": "Desserts", "course": "Desserts", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 10, "cook_time_minutes": 140, "total_time_minutes": 210, "servings": 20, "image_url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "alt": "Homemade Colombian arequipe from milk and sugar"}], "video_urls": [], "keywords": ["Homemade Colombian arequipe from milk and sugar"], "nutrition": {"calories": 82, "protein_g": 1.6, "carbs_g": 15, "fat_g": 1.7, "serving_size": "1 of 20 servings, about 25 g", "estimated": true, "note": "Estimated per serving; yield, moisture and brands affect the values.", "source": "USDA FoodData Central generic whole milk and sugar composition", "method": "1030 g whole milk (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat/100 g) plus250 g sugar (400 kcal and100 g carbohydrate/100 g), divided by20. Small vanilla contribution rounded into calories. Assumed500 g yield,25 g/portion. No whey drained; only water evaporated."}, "seo": {"title": "Homemade Colombian arequipe from milk and sugar", "description": "Make Colombian arequipe from milk and sugar without cooking cans. Photos show color and thickness, approximate yield and refrigerated storage guidance.", "author": "Néstor Bastidas", "image_alt": "Homemade Colombian arequipe from milk and sugar", "image_variants": ["https://manualdecocina.com/recetas/arequipe-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-16x9.webp"], "faq": [{"q": "Is it the same as Valle-style manjar blanco?", "a": "Not in this collection. Manjar blanco has its own recipe; this arequipe has no rice or starch."}, {"q": "Can I cook a sealed can?", "a": "This method cooks milk and sugar in an open pot. Do not heat sealed cans to follow it."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "de", "slug": "arequipe-kolumbianische-milchkaramellcreme", "public_path": "/de/arequipe-kolumbianische-milchkaramellcreme", "title": "Arequipe aus Milch und Zucker selber machen", "excerpt": "Kolumbianisches Arequipe aus Milch und Zucker kochen, ohne Dosen zu erhitzen. Fotos zeigen Farbe und Konsistenz, ungefähre Ausbeute und gekühlte Lagerung.", "summary": "Arequipe entsteht, wenn Milch und Zucker langsam zu einer braunen streichfähigen Creme einkochen. Dieses Rezept enthält keinen Reis und keine Stärke und unterscheidet sich vom Manjar blanco aus dem Valle. Es ergibt etwa 500 g.", "content_html": "<p>Arequipe entsteht, wenn Milch und Zucker langsam zu einer braunen streichfähigen Creme einkochen. Dieses Rezept enthält keinen Reis und keine Stärke und unterscheidet sich vom Manjar blanco aus dem Valle. Es ergibt etwa 500 g.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>Abgedeckt vorsichtshalber in 5–7 Tagen verbrauchen. Zu feste Portion mit etwas heißer Milch lockern und bald verbrauchen. Beim Verdoppeln passende Topfgröße wählen und nach Konsistenz gehen, nicht automatisch die Zeit verdoppeln. Nicht küchenerprobt. Enthält Milch. Saubere, desinfizierte Geräte verwenden und bei höchstens 4 °C lagern. Dies ist keine ungekühlt haltbare Konserve.</p><ul><li><a href=\"https://www.mycolombianrecipes.com/arequipe-or-dulce-de-leche/\">My Colombian Recipes — arequipe cooking technique</a></li><li><a href=\"https://movil.colombiaaprende.edu.co/sites/default/files/files_public/aprenderencasa/secretos-para-contar/la-casa-y-el-campo.pdf\">Secretos para contar — milk sweets, cultural reference</a></li></ul>", "ingredients": [{"name": "pasteurisierte Vollmilch", "amount": "1000", "unit": "ml"}, {"name": "weißer Zucker", "amount": "250", "unit": "g"}, {"name": "lebensmittelechtes Natron", "amount": "1", "unit": "g"}, {"name": "Vanilleextrakt", "amount": "3", "unit": "ml"}], "steps": [{"title": "Mischen und erhitzen", "content": "Milch, Zucker und Natron in einen breiten hohen Topf mit dickem Boden geben. Bei mittlerer bis kleiner Hitze rühren, bis der Zucker gelöst ist. Bei aufsteigendem Schaum Hitze senken; ausreichend Platz gegen Überkochen lassen.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-01.webp", "image_alt": "Mischen und erhitzen — Arequipe aus Milch und Zucker selber machen"}, {"title": "Geduldig einkochen", "content": "Offen bei kleiner Hitze etwa 90–140 Minuten kochen. Regelmäßig über den Boden rühren, bei Bräunung und Eindicken fast ständig. Nur sanft blubbern lassen und Anbrennen vermeiden.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-02.webp", "image_alt": "Geduldig einkochen — Arequipe aus Milch und Zucker selber machen"}, {"title": "Konsistenz prüfen", "content": "Am Ende Vanille einrühren. Ein Löffel soll am Boden eine Spur hinterlassen, die sich erst nach einigen Sekunden schließt. Eine Probe auf kaltem Teller soll dick und streichbar sein. Etwas flüssiger vom Herd nehmen, da sie nachdickt; etwa 500 g Ausbeute.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-03.webp", "image_alt": "Konsistenz prüfen — Arequipe aus Milch und Zucker selber machen"}, {"title": "Abkühlen und lagern", "content": "In ein sauberes hitzefestes Gefäß füllen. Im kalten Wasserbad ohne Wassereintritt gelegentlich rührend abkühlen. Innerhalb von 2 Stunden kühlen und vor dem Servieren ungefähr 1 Stunde warten.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-04.webp", "image_alt": "Abkühlen und lagern — Arequipe aus Milch und Zucker selber machen"}], "category": "Desserts", "course": "Desserts", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 10, "cook_time_minutes": 140, "total_time_minutes": 210, "servings": 20, "image_url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "alt": "Arequipe aus Milch und Zucker selber machen"}], "video_urls": [], "keywords": ["Arequipe aus Milch und Zucker selber machen"], "nutrition": {"calories": 82, "protein_g": 1.6, "carbs_g": 15, "fat_g": 1.7, "serving_size": "1 von 20 Portionen, etwa 25 g", "estimated": true, "note": "Schätzung pro Portion; Ausbeute, Feuchtigkeit und Produkte beeinflussen die Werte.", "source": "USDA FoodData Central generic whole milk and sugar composition", "method": "1030 g whole milk (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat/100 g) plus250 g sugar (400 kcal and100 g carbohydrate/100 g), divided by20. Small vanilla contribution rounded into calories. Assumed500 g yield,25 g/portion. No whey drained; only water evaporated."}, "seo": {"title": "Arequipe aus Milch und Zucker selber machen", "description": "Kolumbianisches Arequipe aus Milch und Zucker kochen, ohne Dosen zu erhitzen. Fotos zeigen Farbe und Konsistenz, ungefähre Ausbeute und gekühlte Lagerung.", "author": "Néstor Bastidas", "image_alt": "Arequipe aus Milch und Zucker selber machen", "image_variants": ["https://manualdecocina.com/recetas/arequipe-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-16x9.webp"], "faq": [{"q": "Ist es Manjar blanco aus dem Valle?", "a": "In dieser Sammlung nicht. Manjar blanco hat ein eigenes Rezept; dieses Arequipe enthält weder Reis noch Stärke."}, {"q": "Kann ich eine geschlossene Dose kochen?", "a": "Dieses Verfahren erhitzt Milch und Zucker im offenen Topf. Dafür keine geschlossenen Dosen erhitzen."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "fr", "slug": "arequipe-colombien-maison", "public_path": "/fr/arequipe-colombien-maison", "title": "Arequipe colombien maison au lait et au sucre", "excerpt": "Préparez l'arequipe avec lait et sucre, sans cuire de boîtes fermées. Photos de la couleur et du point final, rendement et conseils de conservation au frais.", "summary": "L'arequipe est une crème brune à tartiner obtenue en réduisant lentement lait et sucre. Cette recette ne contient ni riz ni amidon et diffère du manjar blanco du Valle. Le rendement approche 500 g selon la réduction.", "content_html": "<p>L&#x27;arequipe est une crème brune à tartiner obtenue en réduisant lentement lait et sucre. Cette recette ne contient ni riz ni amidon et diffère du manjar blanco du Valle. Le rendement approche 500 g selon la réduction.</p>", "notes": "<h3>Conseils et conservation</h3><p>Gardez couvert et utilisez sous 5–7 jours par prudence. Détendez une portion trop ferme avec un peu de lait chaud et utilisez rapidement. Pour doubler, adaptez la casserole et fiez-vous à la texture, sans doubler automatiquement la durée. Non testée en cuisine. Contient du lait. Utilisez du matériel propre et désinfecté et conservez à 4 °C maximum. Cette préparation ne se conserve pas à température ambiante.</p><ul><li><a href=\"https://www.mycolombianrecipes.com/arequipe-or-dulce-de-leche/\">My Colombian Recipes — arequipe cooking technique</a></li><li><a href=\"https://movil.colombiaaprende.edu.co/sites/default/files/files_public/aprenderencasa/secretos-para-contar/la-casa-y-el-campo.pdf\">Secretos para contar — milk sweets, cultural reference</a></li></ul>", "ingredients": [{"name": "lait entier pasteurisé", "amount": "1000", "unit": "ml"}, {"name": "sucre blanc", "amount": "250", "unit": "g"}, {"name": "bicarbonate de sodium alimentaire", "amount": "1", "unit": "g"}, {"name": "extrait de vanille", "amount": "3", "unit": "ml"}], "steps": [{"title": "Mélangez et chauffez", "content": "Réunissez lait, sucre et bicarbonate dans une casserole large, haute et épaisse. Remuez à feu moyen-doux pour dissoudre. Baissez quand la mousse monte ; laissez beaucoup d'espace pour éviter le débordement.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-01.webp", "image_alt": "Mélangez et chauffez — Arequipe colombien maison au lait et au sucre"}, {"title": "Réduisez patiemment", "content": "Cuisez à découvert à feu doux environ 90–140 minutes. Remuez souvent le fond, puis presque constamment quand la crème brunit et épaissit. Maintenez de petits bouillons sans brûler.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-02.webp", "image_alt": "Réduisez patiemment — Arequipe colombien maison au lait et au sucre"}, {"title": "Vérifiez le point", "content": "Ajoutez la vanille à la fin. Une cuillère passée sur le fond doit laisser une trace se refermant en quelques secondes. Une cuillerée sur assiette froide doit être épaisse mais tartinable. Retirez un peu plus fluide que souhaité car elle épaissit en refroidissant ; environ 500 g.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-03.webp", "image_alt": "Vérifiez le point — Arequipe colombien maison au lait et au sucre"}, {"title": "Refroidissez et conservez", "content": "Versez dans un récipient propre résistant à la chaleur. Refroidissez au bain d'eau froide sans entrée d'eau en remuant parfois. Réfrigérez avant 2 heures et attendez environ 1 heure pour servir.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-04.webp", "image_alt": "Refroidissez et conservez — Arequipe colombien maison au lait et au sucre"}], "category": "Desserts", "course": "Desserts", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 140, "total_time_minutes": 210, "servings": 20, "image_url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "alt": "Arequipe colombien maison au lait et au sucre"}], "video_urls": [], "keywords": ["Arequipe colombien maison au lait et au sucre"], "nutrition": {"calories": 82, "protein_g": 1.6, "carbs_g": 15, "fat_g": 1.7, "serving_size": "1 des 20 portions, environ 25 g", "estimated": true, "note": "Estimation par portion ; rendement, humidité et marques modifient les valeurs.", "source": "USDA FoodData Central generic whole milk and sugar composition", "method": "1030 g whole milk (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat/100 g) plus250 g sugar (400 kcal and100 g carbohydrate/100 g), divided by20. Small vanilla contribution rounded into calories. Assumed500 g yield,25 g/portion. No whey drained; only water evaporated."}, "seo": {"title": "Arequipe colombien maison au lait et au sucre", "description": "Préparez l'arequipe avec lait et sucre, sans cuire de boîtes fermées. Photos de la couleur et du point final, rendement et conseils de conservation au frais.", "author": "Néstor Bastidas", "image_alt": "Arequipe colombien maison au lait et au sucre", "image_variants": ["https://manualdecocina.com/recetas/arequipe-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-16x9.webp"], "faq": [{"q": "Est-ce le manjar blanco du Valle ?", "a": "Pas dans cette collection. Il a sa propre recette ; cet arequipe ne contient ni riz ni amidon."}, {"q": "Peut-on chauffer une boîte fermée ?", "a": "Cette méthode cuit lait et sucre dans une casserole ouverte. Ne chauffez pas de boîtes fermées pour la suivre."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "it", "slug": "arequipe-colombiano-fatto-in-casa", "public_path": "/it/arequipe-colombiano-fatto-in-casa", "title": "Arequipe colombiano fatto in casa con latte e zucchero", "excerpt": "Prepara arequipe da latte e zucchero senza cuocere lattine. Foto del colore e del punto finale, resa indicativa e consigli di conservazione in frigorifero.", "summary": "L'arequipe si ottiene riducendo lentamente latte e zucchero in una crema marrone spalmabile. Questa ricetta è senza riso o amido e differisce dal manjar blanco del Valle. Rende circa 500 g secondo la riduzione.", "content_html": "<p>L&#x27;arequipe si ottiene riducendo lentamente latte e zucchero in una crema marrone spalmabile. Questa ricetta è senza riso o amido e differisce dal manjar blanco del Valle. Rende circa 500 g secondo la riduzione.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Conserva coperto e usa entro 5–7 giorni come indicazione prudente. Ammorbidisci una porzione troppo soda con poco latte caldo e usala presto. Raddoppiando, adatta la pentola e controlla il punto senza raddoppiare automaticamente il tempo. Non testato in cucina. Contiene latte. Usa utensili puliti e igienizzati e conserva a 4 °C o meno. Non è una conserva da tenere a temperatura ambiente.</p><ul><li><a href=\"https://www.mycolombianrecipes.com/arequipe-or-dulce-de-leche/\">My Colombian Recipes — arequipe cooking technique</a></li><li><a href=\"https://movil.colombiaaprende.edu.co/sites/default/files/files_public/aprenderencasa/secretos-para-contar/la-casa-y-el-campo.pdf\">Secretos para contar — milk sweets, cultural reference</a></li></ul>", "ingredients": [{"name": "latte intero pastorizzato", "amount": "1000", "unit": "ml"}, {"name": "zucchero bianco", "amount": "250", "unit": "g"}, {"name": "bicarbonato di sodio alimentare", "amount": "1", "unit": "g"}, {"name": "estratto di vaniglia", "amount": "3", "unit": "ml"}], "steps": [{"title": "Mescola e scalda", "content": "Metti latte, zucchero e bicarbonato in una pentola larga, alta e a fondo spesso. Mescola a fuoco medio-basso fino a sciogliere. Abbassa quando sale la schiuma; lascia spazio per non far traboccare.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-01.webp", "image_alt": "Mescola e scalda — Arequipe colombiano fatto in casa con latte e zucchero"}, {"title": "Riduci con pazienza", "content": "Cuoci scoperto a fuoco basso circa 90–140 minuti. Mescola spesso sul fondo, poi quasi continuamente quando scurisce e addensa. Mantieni un bollore leggero evitando bruciature.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-02.webp", "image_alt": "Riduci con pazienza — Arequipe colombiano fatto in casa con latte e zucchero"}, {"title": "Controlla il punto", "content": "Aggiungi la vaniglia alla fine. Il cucchiaio sul fondo deve lasciare una traccia che si richiude dopo qualche secondo. Una prova su piatto freddo deve essere densa ma spalmabile. Togli un po' più fluido del desiderato perché addensa raffreddando; resa circa 500 g.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-03.webp", "image_alt": "Controlla il punto — Arequipe colombiano fatto in casa con latte e zucchero"}, {"title": "Raffredda e conserva", "content": "Trasferisci in recipiente pulito resistente al calore. Raffredda in acqua fredda senza farla entrare, mescolando ogni tanto. Refrigera entro 2 ore e attendi circa 1 ora per servire.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-04.webp", "image_alt": "Raffredda e conserva — Arequipe colombiano fatto in casa con latte e zucchero"}], "category": "Dolci", "course": "Dolci", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 140, "total_time_minutes": 210, "servings": 20, "image_url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "alt": "Arequipe colombiano fatto in casa con latte e zucchero"}], "video_urls": [], "keywords": ["Arequipe colombiano fatto in casa con latte e zucchero"], "nutrition": {"calories": 82, "protein_g": 1.6, "carbs_g": 15, "fat_g": 1.7, "serving_size": "1 di 20 porzioni, circa 25 g", "estimated": true, "note": "Stima per porzione; resa, umidità e prodotti possono cambiare i valori.", "source": "USDA FoodData Central generic whole milk and sugar composition", "method": "1030 g whole milk (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat/100 g) plus250 g sugar (400 kcal and100 g carbohydrate/100 g), divided by20. Small vanilla contribution rounded into calories. Assumed500 g yield,25 g/portion. No whey drained; only water evaporated."}, "seo": {"title": "Arequipe colombiano fatto in casa con latte e zucchero", "description": "Prepara arequipe da latte e zucchero senza cuocere lattine. Foto del colore e del punto finale, resa indicativa e consigli di conservazione in frigorifero.", "author": "Néstor Bastidas", "image_alt": "Arequipe colombiano fatto in casa con latte e zucchero", "image_variants": ["https://manualdecocina.com/recetas/arequipe-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-16x9.webp"], "faq": [{"q": "È il manjar blanco del Valle?", "a": "Non in questa raccolta. Ha una ricetta propria; questo arequipe non contiene riso né amido."}, {"q": "Posso cuocere una lattina chiusa?", "a": "Questo metodo usa latte e zucchero in pentola aperta. Non scaldare lattine chiuse per seguirlo."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "ja", "slug": "homemade-colombian-arequipe", "public_path": "/ja/homemade-colombian-arequipe", "title": "牛乳と砂糖から作るコロンビアのアレキペ", "excerpt": "缶を加熱せず、牛乳と砂糖から作るアレキペ。茶色く濃厚になる変化と仕上がりの固さを工程写真で解説し、出来上がり量、冷却、冷蔵保存の目安も紹介します。", "summary": "牛乳と砂糖をゆっくり煮詰め、茶色い濃厚なミルクスプレッドにします。米やでんぷんは使わず、バジェ地方のマンハール・ブランコとは別のレシピです。煮詰め方により約500 gできます。", "content_html": "<p>牛乳と砂糖をゆっくり煮詰め、茶色い濃厚なミルクスプレッドにします。米やでんぷんは使わず、バジェ地方のマンハール・ブランコとは別のレシピです。煮詰め方により約500 gできます。</p>", "notes": "<h3>コツと保存</h3><p>ふたをして冷蔵し、慎重な目安として5〜7日以内に使います。固すぎる一回分は温かい牛乳を少量混ぜ、早めに使います。倍量では鍋を調整し、時間を単純に倍にせず仕上がりで判断します。調理試験は行っていません。 乳を含みます。清潔に洗浄・消毒した器具を使い、4 ℃以下で冷蔵してください。常温保存用の瓶詰めではありません。</p><ul><li><a href=\"https://www.mycolombianrecipes.com/arequipe-or-dulce-de-leche/\">My Colombian Recipes — arequipe cooking technique</a></li><li><a href=\"https://movil.colombiaaprende.edu.co/sites/default/files/files_public/aprenderencasa/secretos-para-contar/la-casa-y-el-campo.pdf\">Secretos para contar — milk sweets, cultural reference</a></li></ul>", "ingredients": [{"name": "殺菌済みの全乳", "amount": "1000", "unit": "ml"}, {"name": "白砂糖", "amount": "250", "unit": "g"}, {"name": "食品用重曹", "amount": "1", "unit": "g"}, {"name": "バニラエッセンス", "amount": "3", "unit": "ml"}], "steps": [{"title": "混ぜて温める", "content": "広く深い厚手の鍋に牛乳、砂糖、重曹を入れ、弱めの中火で混ぜて溶かします。泡が上がったら弱火にします。吹きこぼれないよう鍋に十分な余裕を持たせます。", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-01.webp", "image_alt": "混ぜて温める — 牛乳と砂糖から作るコロンビアのアレキペ"}, {"title": "ゆっくり煮詰める", "content": "ふたをせず弱火で約90〜140分煮ます。鍋底をこまめに混ぜ、茶色く濃くなったらほぼ絶えず混ぜます。小さく泡立つ程度を保ち、焦がしません。", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-02.webp", "image_alt": "ゆっくり煮詰める — 牛乳と砂糖から作るコロンビアのアレキペ"}, {"title": "仕上がりを確認する", "content": "最後にバニラを加えます。鍋底をスプーンでなぞった跡が数秒残るのが目安です。冷たい皿の一さじが濃く塗りやすくなれば、冷めて固くなる分、少し緩めで火を止めます。目安量は約500 gです。", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-03.webp", "image_alt": "仕上がりを確認する — 牛乳と砂糖から作るコロンビアのアレキペ"}, {"title": "冷まして保存する", "content": "清潔な耐熱容器に移します。中に水が入らないよう冷水に当て、時々混ぜて冷まします。2時間以内に冷蔵し、食べる前に約1時間冷まします。", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-04.webp", "image_alt": "冷まして保存する — 牛乳と砂糖から作るコロンビアのアレキペ"}], "category": "デザート", "course": "デザート", "cuisine": "各国料理", "difficulty": "簡単", "prep_time_minutes": 10, "cook_time_minutes": 140, "total_time_minutes": 210, "servings": 20, "image_url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "alt": "牛乳と砂糖から作るコロンビアのアレキペ"}], "video_urls": [], "keywords": ["牛乳と砂糖から作るコロンビアのアレキペ"], "nutrition": {"calories": 82, "protein_g": 1.6, "carbs_g": 15, "fat_g": 1.7, "serving_size": "20食分の1、約25 g", "estimated": true, "note": "1食分の推定値です。出来上がり量、水分、製品により異なります。", "source": "USDA FoodData Central generic whole milk and sugar composition", "method": "1030 g whole milk (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat/100 g) plus250 g sugar (400 kcal and100 g carbohydrate/100 g), divided by20. Small vanilla contribution rounded into calories. Assumed500 g yield,25 g/portion. No whey drained; only water evaporated."}, "seo": {"title": "牛乳と砂糖から作るコロンビアのアレキペ", "description": "缶を加熱せず、牛乳と砂糖から作るアレキペ。茶色く濃厚になる変化と仕上がりの固さを工程写真で解説し、出来上がり量、冷却、冷蔵保存の目安も紹介します。", "author": "Néstor Bastidas", "image_alt": "牛乳と砂糖から作るコロンビアのアレキペ", "image_variants": ["https://manualdecocina.com/recetas/arequipe-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-16x9.webp"], "faq": [{"q": "マンハール・ブランコと同じですか。", "a": "このコレクションでは別です。そちらは独立したレシピがあり、このアレキペには米やでんぷんを使いません。"}, {"q": "密閉缶を加熱してもよいですか。", "a": "この製法は牛乳と砂糖をふたのない鍋で煮ます。密閉缶を加熱しないでください。"}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "pt", "slug": "arequipe-colombiano-caseiro", "public_path": "/pt/arequipe-colombiano-caseiro", "title": "Arequipe colombiano caseiro com leite e açúcar", "excerpt": "Faça arequipe com leite e açúcar sem cozinhar latas. Fotos mostram cor e ponto final, com rendimento aproximado e dicas para conservar na geladeira.", "summary": "Arequipe é leite e açúcar reduzidos lentamente até formar um creme marrom espesso. Esta versão não leva arroz ou amido e difere do manjar blanco do Valle. Rende aproximadamente 500 g conforme a redução.", "content_html": "<p>Arequipe é leite e açúcar reduzidos lentamente até formar um creme marrom espesso. Esta versão não leva arroz ou amido e difere do manjar blanco do Valle. Rende aproximadamente 500 g conforme a redução.</p>", "notes": "<h3>Dicas e conservação</h3><p>Conserve tampado e use em 5–7 dias como orientação prudente. Se firme demais, amoleça uma porção com pouco leite quente e use logo. Ao dobrar, adapte a panela e siga o ponto, sem dobrar automaticamente o tempo. Sem teste de cozinha próprio. Contém leite. Use utensílios limpos e higienizados e conserve a 4 °C ou menos. Não é uma conserva para guardar à temperatura ambiente.</p><ul><li><a href=\"https://www.mycolombianrecipes.com/arequipe-or-dulce-de-leche/\">My Colombian Recipes — arequipe cooking technique</a></li><li><a href=\"https://movil.colombiaaprende.edu.co/sites/default/files/files_public/aprenderencasa/secretos-para-contar/la-casa-y-el-campo.pdf\">Secretos para contar — milk sweets, cultural reference</a></li></ul>", "ingredients": [{"name": "leite integral pasteurizado", "amount": "1000", "unit": "ml"}, {"name": "açúcar branco", "amount": "250", "unit": "g"}, {"name": "bicarbonato de sódio alimentício", "amount": "1", "unit": "g"}, {"name": "extrato de baunilha", "amount": "3", "unit": "ml"}], "steps": [{"title": "Misture e aqueça", "content": "Coloque leite, açúcar e bicarbonato numa panela larga, alta e de fundo grosso. Mexa em fogo médio-baixo até dissolver. Abaixe quando subir espuma; deixe espaço para não transbordar.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-01.webp", "image_alt": "Misture e aqueça — Arequipe colombiano caseiro com leite e açúcar"}, {"title": "Reduza com paciência", "content": "Cozinhe destampado em fogo baixo por cerca de 90–140 minutos. Mexa o fundo frequentemente e quase sem parar quando dourar e engrossar. Mantenha borbulhas suaves sem queimar.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-02.webp", "image_alt": "Reduza com paciência — Arequipe colombiano caseiro com leite e açúcar"}, {"title": "Confira o ponto", "content": "Adicione baunilha no final. A colher no fundo deve abrir um caminho que leve alguns segundos para fechar. Uma colherada em prato frio fica espessa mas espalhável. Retire um pouco mais fluido porque firma ao esfriar; rende cerca de 500 g.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-03.webp", "image_alt": "Confira o ponto — Arequipe colombiano caseiro com leite e açúcar"}, {"title": "Esfrie e guarde", "content": "Passe para recipiente limpo resistente ao calor. Esfrie em banho de água fria sem entrar água, mexendo às vezes. Refrigere antes de 2 horas e espere cerca de 1 hora para servir.", "image_url": "https://manualdecocina.com/recetas/arequipe-casero/paso-04.webp", "image_alt": "Esfrie e guarde — Arequipe colombiano caseiro com leite e açúcar"}], "category": "Sobremesas", "course": "Sobremesas", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 140, "total_time_minutes": 210, "servings": 20, "image_url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/arequipe-casero/portada.webp", "alt": "Arequipe colombiano caseiro com leite e açúcar"}], "video_urls": [], "keywords": ["Arequipe colombiano caseiro com leite e açúcar"], "nutrition": {"calories": 82, "protein_g": 1.6, "carbs_g": 15, "fat_g": 1.7, "serving_size": "1 de 20 porções, cerca de 25 g", "estimated": true, "note": "Estimativa por porção; rendimento, umidade e marcas alteram os valores.", "source": "USDA FoodData Central generic whole milk and sugar composition", "method": "1030 g whole milk (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat/100 g) plus250 g sugar (400 kcal and100 g carbohydrate/100 g), divided by20. Small vanilla contribution rounded into calories. Assumed500 g yield,25 g/portion. No whey drained; only water evaporated."}, "seo": {"title": "Arequipe colombiano caseiro com leite e açúcar", "description": "Faça arequipe com leite e açúcar sem cozinhar latas. Fotos mostram cor e ponto final, com rendimento aproximado e dicas para conservar na geladeira.", "author": "Néstor Bastidas", "image_alt": "Arequipe colombiano caseiro com leite e açúcar", "image_variants": ["https://manualdecocina.com/recetas/arequipe-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/arequipe-casero/portada-16x9.webp"], "faq": [{"q": "É igual ao manjar blanco do Valle?", "a": "Não nesta coleção. Ele tem receita própria; este arequipe não leva arroz nem amido."}, {"q": "Posso cozinhar uma lata fechada?", "a": "Este método cozinha leite e açúcar em panela aberta. Não aqueça latas fechadas para segui-lo."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}]$payload$::jsonb;
foods jsonb := $foods$[]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "leche", "alias": "leche entera pasteurizada"}, {"slug": "azucar", "alias": "azúcar blanco"}, {"slug": "bicarbonato-de-sodio", "alias": "bicarbonato de sodio alimentario"}, {"slug": "extracto-de-vainilla", "alias": "extracto de vainilla"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),'Ingrediente para elaboraciones lácteas domésticas.','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>4 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
FOR v IN SELECT * FROM public.recipes WHERE recipe_group_id=group_id LOOP
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 UPDATE public.recipes SET editorial_status='published' WHERE id=v.id;
END LOOP;
END $dairy$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id=(SELECT recipe_group_id FROM public.recipes WHERE language='es' AND slug='arequipe-casero') ORDER BY language;
